import com.oracle.e1.common.OrchestrationAttributes
import groovy.json.JsonOutput
import java.nio.file.Files
import java.nio.file.Path
import java.nio.file.Paths

HashMap<String, Object> main(OrchestrationAttributes orchAttr, HashMap inputMap) {
    HashMap<String, Object> returnMap = new HashMap<String, Object>()

    // Lista final de archivos encontrados en todos los directorios.
    def filesList = []

    // Builder para mostrar todo en un solo writeWarn.
    StringBuilder message = new StringBuilder()

    // Recupero todos los par\Ufffffffftros que empiecen con dirPath.
    // Ejemplo: dirPath1, dirPath2, dirPath3, etc.
    def dirKeys = inputMap.keySet()
        .findAll { key -> key != null && key.toString().matches(/^dirPath\d+$/) }
        .sort { a, b -> extractDirIndex(a.toString()) <=> extractDirIndex(b.toString()) }

    // Compatibilidad opcional con el par\Ufffffffftro anterior dirPath.
    if (inputMap.get("dirPath") != null && inputMap.get("dirPath").toString().trim()) {
        dirKeys = (["dirPath"] + dirKeys).unique()
    }

    // Si no se recibi\Uffffffffng\Uffffffffrectorio, informo y salgo.
    if (dirKeys == null || dirKeys.isEmpty()) {
        orchAttr.writeWarn("No se recibieron par\Ufffffffftros dirPath para procesar.")
        returnMap.put("filesCount", 0)
        returnMap.put("fileArray", "[]")
        return returnMap
    }

    // Recorro todos los dirPath recibidos.
    dirKeys.each { key ->
        String dirPath = ((String) inputMap.get(key))?.trim()

        // Solo proceso si el valor tiene contenido.
        if (dirPath) {
            Path directory = Paths.get(dirPath)

            // Separador entre bloques de directorios.
            if (message.length() > 0) {
                message.append("\n")
            }

            message.append("Directorio [${key}]: ${dirPath}")

            // Validaciones del directorio.
            if (!Files.exists(directory)) {
                message.append("\n")
                message.append("El directorio no existe.")
                return
            }

            if (!Files.isDirectory(directory)) {
                message.append("\n")
                message.append("La ruta no es un directorio.")
                return
            }

            // Recorro el directorio y acumulo todo en el mismo mensaje.
            def localCount = 0
            def stream = Files.list(directory)

            try {
                stream
                    .filter { path -> Files.isRegularFile(path) }
                    .sorted()
                    .forEach { path ->
                        def fileName = path.getFileName().toString()
                        def fileSize = Files.size(path)

                        filesList << [
                            dirKey  : key,
                            dirPath : dirPath,
                            fileName: fileName,
                            fullPath: path.toString(),
                            size    : fileSize.toString()
                        ]

                        localCount++

                        message.append("\n")
                        message.append("Archivo: ${fileName} - Size: ${fileSize} bytes")
                    }
            } finally {
                stream.close()
            }

            if (localCount == 0) {
                message.append("\n")
                message.append("No se encontraron archivos en este directorio.")
            } else {
                message.append("\n")
                message.append("Cantidad de archivos encontrados en ${key}: ${localCount}")
            }
        }
    }

    // Si no hubo ning\Uffffffffnsaje \Uffffffff lo informo.
    if (message.length() == 0) {
        message.append("No se encontraron directorios con valor para procesar.")
    }

    // Muestro todo en un solo mensaje.
    orchAttr.writeWarn(message.toString())

    // Devuelvo los resultados.
    returnMap.put("filesCount", filesList.size())
    returnMap.put("fileArray", JsonOutput.toJson(filesList))

    return returnMap
}

// Extrae el n\Uffffffff de un par\Ufffffffftro tipo dirPathN para poder ordenarlos.
Integer extractDirIndex(String key) {
    def matcher = (key =~ /^dirPath(\d+)$/)
    if (matcher.matches()) {
        return matcher[0][1].toInteger()
    }
    return 0
}

