 *
 * Reglas:
 * - procesa todas las ocurrencias de jde__simpleMessage
 * - separa errores por \n(X)
 * - no repite errores
 * - no devuelve la cabecera previa al primer \n(X)
 */
List<Map<String, String>> getJdeSimpleMessageErrors(String jsonText) {
    List<Map<String, String>> result = new ArrayList<Map<String, String>>()

    if (jsonText == null || jsonText.isEmpty()) {
        return result
    }

    LinkedHashSet<String> uniqueErrors = new LinkedHashSet<String>()
    List<String> simpleMessages = getJsonStringValuesByKey(jsonText, "jde__simpleMessage")

    simpleMessages.each { String simpleMessage ->
        List<String> extractedErrors = extractErrorsFromJdeSimpleMessage(simpleMessage)

        extractedErrors.each { String errorText ->
            if (errorText != null && !errorText.trim().isEmpty()) {
                uniqueErrors.add(errorText.trim())
            }
        }
    }

    uniqueErrors.each { String errorText ->
        result.add(["error": errorText])
    }

    return result
}

/**
 * Recupera todos los values string de un key específico dentro del texto JSON,
 * sin parsear el JSON completo.
 */
List<String> getJsonStringValuesByKey(String jsonText, String targetKey) {
    List<String> values = new ArrayList<String>()
    int i = 0

    while (i < jsonText.length()) {
        char currentChar = jsonText.charAt(i)

        if (currentChar == '"') {
            Map keyToken = readJsonStringToken(jsonText, i)
            int nextIndex = skipWhitespace(jsonText, ((Integer) keyToken.endIndex).intValue())

            if (nextIndex < jsonText.length() && jsonText.charAt(nextIndex) == ':') {
                if (targetKey.equals((String) keyToken.value)) {
                    int valueStart = skipWhitespace(jsonText, nextIndex + 1)

                    if (valueStart < jsonText.length() && jsonText.charAt(valueStart) == '"') {
                        Map valueToken = readJsonStringToken(jsonText, valueStart)
                        values.add((String) valueToken.value)
                        i = ((Integer) valueToken.endIndex).intValue()
                        continue
                    }
                }
            }

            i = ((Integer) keyToken.endIndex).intValue()
            continue
        }

        i++
    }

    return values
}

