 *
 * Ejemplo:
 * "texto cabecera\n(1) error uno\n(2) error dos"
 *
 * Resultado:
 * ["error uno", "error dos"]
 */
List<String> extractErrorsFromJdeSimpleMessage(String simpleMessage) {
    List<String> errors = new ArrayList<String>()

    if (simpleMessage == null || simpleMessage.isEmpty()) {
        return errors
    }

    def matcher = (simpleMessage =~ /\n\((\d+)\)\s*/)
    List<Integer> starts = new ArrayList<Integer>()

    while (matcher.find()) {
        starts.add(matcher.start())
    }

    if (starts.isEmpty()) {
        return errors
    }

    for (int i = 0; i < starts.size(); i++) {
        int start = starts.get(i)
        int end = (i + 1 < starts.size()) ? starts.get(i + 1) : simpleMessage.length()

        String chunk = simpleMessage.substring(start, end)

        // Remueve solo el prefijo "\n(X)" del inicio del bloque
        chunk = chunk.replaceFirst(/^\n\(\d+\)\s*/, "")

        if (chunk != null && !chunk.trim().isEmpty()) {
            errors.add(chunk.trim())
        }
    }

    return errors
}

/**
 * Lee un string JSON y lo devuelve decodificado.
 * Maneja escapes: \", \\, \/, \b, \f, \n, \r, \t,
 */
Map readJsonStringToken(String text, int startIndex) {
    if (text.charAt(startIndex) != '"') {
        throw new IllegalArgumentException("La posición ${startIndex} no apunta al inicio de un string JSON")
    }

    StringBuilder sb = new StringBuilder()
    int i = startIndex + 1

    while (i < text.length()) {
        char ch = text.charAt(i)

        if (ch == '"') {
            return [
                value   : sb.toString(),
                endIndex: Integer.valueOf(i + 1)
            ]
        }

        if (ch == '\\') {
            if (i + 1 >= text.length()) {
                throw new IllegalArgumentException("Escape inválido en la posición ${i}")
            }

            char esc = text.charAt(i + 1)

            switch (esc) {
                case '"':
                    sb.append('"')
                    i += 2
                    continue
                case '\\':
                    sb.append('\\')
                    i += 2
                    continue
                case '/':
                    sb.append('/')
                    i += 2
                    continue
                case 'b':
                    sb.append('\b')
                    i += 2
                    continue
                case 'f':
                    sb.append('\f')
                    i += 2
                    continue
                case 'n':
                    sb.append('\n')
                    i += 2
                    continue
                case 'r':
                    sb.append('\r')
                    i += 2
                    continue
                case 't':
                    sb.append('\t')
                    i += 2
                    continue
                case 'u':
                    if (i + 5 >= text.length()) {
                        throw new IllegalArgumentException("Secuencia unicode inválida en la posición ${i}")
                    }

                    String hex = text.substring(i + 2, i + 6)
                    sb.append((char) Integer.parseInt(hex, 16))
                    i += 6
                    continue
                default:
                    sb.append(esc)
                    i += 2
                    continue
            }
        }

        sb.append(ch)
        i++
    }

    throw new IllegalArgumentException("String JSON sin cierre desde la posición ${startIndex}")
}

/**
 * Salta espacios en blanco desde una posición.
 */
int skipWhitespace(String text, int index) {
    int i = index

    while (i < text.length() && Character.isWhitespace(text.charAt(i))) {
        i++
    }

    return i
}

